const agora = DateTime.now().setZone('America/Sao_Paulo');
const nomeArquivo = `BEAUTYFLOW3.1-backup-${agora.toFormat('yyyy-MM-dd-HHmm')}`;

return [{ json: {
  // WF016 é um workflow de escopo GLOBAL (não recebe id_empresa): 'GLOBAL' é um valor
  // explícito e documentado, nunca uma string vazia silenciosa, para deixar isso claro
  // na aba LOGS em vez de parecer um campo esquecido.
  id_empresa: 'GLOBAL',
  nome_arquivo: nomeArquivo,
  agora_iso: agora.toISO()
} }];

const resultado = $json;
const prep = $('CODE - Preparar Backup').first().json;

const arquivoId = resultado.id || '';
const arquivoNome = resultado.name || prep.nome_arquivo;
const criadoComSucesso = !!arquivoId;

if (!criadoComSucesso) {
  return [{ json: {
    ...prep, criado: false, arquivo_id: '', arquivo: arquivoNome,
    evento_resultado: 'ERRO_BACKUP',
    node_origem: 'DRIVE - Copiar Planilha',
    erro: 'A cópia da planilha foi executada mas não retornou um ID de arquivo válido.'
  } }];
}

return [{ json: {
  ...prep, criado: true, arquivo_id: arquivoId, arquivo: arquivoNome,
  evento_resultado: 'BACKUP_CONCLUIDO', node_origem: 'DRIVE - Copiar Planilha', erro: ''
} }];

const prep = $('CODE - Preparar Backup').first().json;
const err = $json.error || {};

return [{ json: {
  ...prep, criado: false, arquivo_id: '', arquivo: prep.nome_arquivo,
  evento_resultado: 'ERRO_BACKUP',
  node_origem: 'DRIVE - Copiar Planilha',
  erro: String((err && err.message) || err || 'Falha técnica ao copiar a planilha para o Google Drive.')
} }];

const ctx = $('CODE - Avaliar Backup Criado').first().json;

// Este node agora só recebe o output de SUCESSO de "DRIVE - Listar Backups Existentes"
// (o output de erro técnico foi separado para "CODE - Erro Listagem Backups", que tem seu
// próprio node_origem correto). Isso corrige uma falha real: antes, "items.length === 0" era
// usado como proxy para "a busca falhou tecnicamente", mas o output de erro do Google Drive
// (onError: continueErrorOutput) normalmente entrega 1 item (o objeto de erro), não 0 - ou
// seja, uma falha técnica real nunca era detectada e acabava tratada como "nenhum backup
// expirado encontrado", mascarando o erro silenciosamente.
const PREFIXO = 'BEAUTYFLOW3.1-backup-';
// Proteção extra e explícita: nunca considerar a planilha original do BeautyFlow como candidata
// à exclusão, mesmo que por algum motivo ela apareça nos resultados da busca.
const ID_PLANILHA_ORIGINAL = '1lJtjTZU8xH8rNGZqqMwH8xlmGrUdm4ml-DFR4DOjV6E';
const agora = ctx.agora_iso ? DateTime.fromISO(ctx.agora_iso, { zone: 'America/Sao_Paulo' }) : DateTime.now().setZone('America/Sao_Paulo');

const arquivos = items.map(i => i.json).filter(f => f && f.id && f.name);

const expirados = arquivos.filter(f => {
  // Nunca excluir a planilha original, sob nenhuma circunstância.
  if (f.id === ID_PLANILHA_ORIGINAL) return false;
  // Nunca mexer em arquivo que não pertença exatamente ao padrão de nomenclatura do BeautyFlow.
  if (!String(f.name).startsWith(PREFIXO)) return false;
  const criado = f.createdTime ? DateTime.fromISO(f.createdTime, { zone: 'America/Sao_Paulo' }) : null;
  // Sem metadado de data confiável, não arrisca excluir.
  if (!criado || !criado.isValid) return false;
  const idadeDias = agora.diff(criado, 'days').days;
  return idadeDias > 30;
});

if (expirados.length === 0) {
  return [{ json: { ...ctx, limpeza_realizada: true, tem_expirados: false, limpeza_erro: '' } }];
}

return expirados.map(f => ({ json: {
  ...ctx, limpeza_realizada: true, tem_expirados: true, limpeza_erro: '',
  arquivo_id_excluir: f.id, arquivo_nome_excluir: f.name
} }));

const ctx = $('CODE - Avaliar Backup Criado').first().json;

let excluidos = 0, falhas = 0;
for (const it of items) {
  const j = it.json;
  if (j.deletado === true) excluidos++;
  else if (j.deletado === false) falhas++;
  // "deletado" ausente => ramo "nada a excluir" ou "erro de listagem", não conta.
}

// Preserva o node_origem herdado (ex.: 'DRIVE - Listar Backups Existentes' se a listagem
// falhou), mas se a falha ocorreu na exclusão em si, reatribui o node_origem para o node
// correto (a listagem, nesse caso, funcionou normalmente).
const nodeOrigem = falhas > 0 ? 'DRIVE - Excluir Backup Expirado' : (ctx.node_origem || 'DRIVE - Copiar Planilha');

return [{ json: {
  ...ctx,
  node_origem: nodeOrigem,
  limpeza_backups_excluidos: excluidos,
  limpeza_backups_com_falha: falhas
} }];

return items.map(item => {
  const dados = item.json;

  const criado = dados.criado === true;
  const limpezaErro = String(dados.limpeza_erro || '').trim();
  const erroBackup = String(dados.erro || '').trim();

  let eventoResultado;

  // 1. O próprio backup falhou
  if (!criado) {
    eventoResultado = 'ERRO_BACKUP';
  }

  // 2. Backup criado, mas houve falha na etapa de retenção/limpeza
  else if (limpezaErro !== '') {
    eventoResultado = 'SUCESSO_PARCIAL';
  }

  // 3. Backup criado e retenção processada sem erro
  else {
    eventoResultado = 'BACKUP_CONCLUIDO';
  }

  return {
    json: {
      ...dados,
      evento_resultado: eventoResultado,
      erro: erroBackup,
      limpeza_erro: limpezaErro
    }
  };
});

const ctx = $('CODE - Avaliar Backup Criado').first().json;
const err = $json.error || {};

// O backup do dia (arquivo) já foi criado com sucesso neste ponto - este erro é apenas na
// ETAPA de retenção (listar backups para decidir o que expirou). Por isso não alteramos
// evento_resultado/criado (que seguem refletindo o resultado real do backup), mas
// registramos explicitamente essa falha em limpeza_erro para que o log final da WF017
// não pareça um sucesso completo silenciosamente.
return [{ json: {
  ...ctx, limpeza_realizada: false, tem_expirados: false,
  node_origem: 'DRIVE - Listar Backups Existentes',
  limpeza_erro: String((err && err.message) || err || 'Falha técnica ao listar backups existentes no Google Drive para aplicar a retenção de 30 dias.')
} }];
